// Acessa o base64 que a API retornou
const base64Data = $input.item.json.base64; 

if (!base64Data) {
  throw new Error("Áudio base64 não encontrado.");
}

return {
  json: $input.item.json,
  binary: {
    // Dá um nome para a variável binária (vamos chamar de "data")
    data: {
      data: base64Data,
      mimeType: 'audio/ogg',
      fileExtension: 'ogg',
      fileName: 'audio_cliente.ogg'
